using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." },
        new() { Id = 5, Name = "Biology", Code = "BIO", Description = "Study of living organisms and life processes." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of teaching experience and specializes in programming pedagogy. She holds a Ph.D. from MIT and has published extensively on introductory CS education.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Code = "CS201", Title = "Data Structures and Algorithms", Description = "Advanced study of data organization and algorithm design. Covers trees, graphs, sorting, searching, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park is a renowned researcher in algorithm optimization. Previously at Google Research, he brings industry and academic expertise to the classroom.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Code = "CS301", Title = "Database Systems", Description = "Design and implementation of database management systems. Covers relational algebra, SQL, normalization, and transaction processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez worked as a database architect at Oracle for 10 years before joining academia. Her research focuses on distributed database systems.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Code = "CS401", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of teaching experience and specializes in programming pedagogy. She holds a Ph.D. from MIT and has published extensively on introductory CS education.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 5, Code = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Wright", InstructorBio = "Dr. Wright is an award-winning mathematics educator with over 20 years of experience teaching calculus at the university level.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 6, Code = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to systems of equations.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Lisa Huang", InstructorBio = "Dr. Huang's research spans pure and applied mathematics. She is particularly passionate about making abstract algebra accessible to undergraduates.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 7, Code = "MATH301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", InstructorName = "Dr. Alan Wright", InstructorBio = "Dr. Wright is an award-winning mathematics educator with over 20 years of experience teaching calculus at the university level.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 8, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions for hands-on experimentation.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist who has worked at CERN. He emphasizes connecting theoretical concepts to real-world experiments.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 9, Code = "PHYS201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Lab Fri 1:00–3:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an experimental physicist who has worked at CERN. He emphasizes connecting theoretical concepts to real-world experiments.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true },
        new() { Id = 10, Code = "ENG101", Title = "College Composition", Description = "Develop critical thinking and writing skills through essay composition, research writing, and peer review.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Prof. Diana Blake", InstructorBio = "Prof. Blake is a published author and writing coach. She has helped thousands of students develop strong academic writing skills.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 11, Code = "ENG205", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, examining cultural and historical contexts.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", InstructorName = "Prof. Diana Blake", InstructorBio = "Prof. Blake is a published author and writing coach. She has helped thousands of students develop strong academic writing skills.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
        new() { Id = 12, Code = "BIO101", Title = "Introduction to Biology", Description = "Fundamentals of cell biology, genetics, evolution, and ecology. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed 9:00–10:15 AM + Lab Fri 9:00–11:50 AM", InstructorName = "Dr. Emily Foster", InstructorBio = "Dr. Foster is a molecular biologist whose research on gene expression has been published in Nature and Science.", DepartmentId = 5, DepartmentName = "Biology", IsFeatured = false },
        new() { Id = 13, Code = "BIO301", Title = "Genetics and Genomics", Description = "Molecular genetics, genome organization, gene regulation, and modern genomic technologies.", Credits = 4, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Emily Foster", InstructorBio = "Dr. Foster is a molecular biologist whose research on gene expression has been published in Nature and Science.", DepartmentId = 5, DepartmentName = "Biology", IsFeatured = true },
    ];

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();
}

