@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero-section text-center py-5">
        <h1 class="display-4">University Course Catalog</h1>
        <p class="lead text-muted">Explore our departments and courses for the upcoming semester.</p>
        <a href="/courses" class="btn btn-primary btn-lg mt-2">Browse All Courses</a>
    </div>

    <section class="mb-5">
        <h2 class="mb-3">Featured Courses</h2>
        <div class="row">
            @foreach (var course in _featuredCourses)
            {
                <div class="col-md-4 mb-4">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@course.Code — @course.Title</h5>
                            <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                            <p class="card-text">@Truncate(course.Description, 100)</p>
                        </div>
                        <div class="card-footer bg-transparent">
                            <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>

    <section class="mb-5">
        <h2 class="mb-3">Departments</h2>
        <div class="row">
            @foreach (var dept in _departments)
            {
                <div class="col-md-4 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@dept.Name</h5>
                            <p class="card-text">@dept.Description</p>
                            <a href="/courses?departmentId=@dept.Id" class="btn btn-outline-secondary btn-sm">View Courses</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </section>
</div>

