    private string SearchTerm { get; set; } = string.Empty;
    private int SelectedDepartmentId { get; set; }

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetAllDepartments();

        if (DepartmentId.HasValue)
        {
            SelectedDepartmentId = DepartmentId.Value;
        }

        ApplyFilters();
    }

    private void ApplyFilters()
    {
        int? deptFilter = SelectedDepartmentId > 0 ? SelectedDepartmentId : null;
        _filteredCourses = CatalogService.SearchCourses(SearchTerm, deptFilter);
    }

    private void ClearFilters()
    {
        SearchTerm = string.Empty;
        SelectedDepartmentId = 0;
        ApplyFilters();
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@rendermode InteractiveServer

<PageTitle>Enrollment Request</PageTitle>

<div class="container">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted Successfully</h4>
            <p>Thank you, <strong>@_model.StudentName</strong>! Your enrollment request for
               <strong>@_selectedCourseTitle</strong> has been received.</p>
            <p>You will receive a confirmation at your university email within 2–3 business days.</p>
            <a href="/courses" class="btn btn-primary">Back to Courses</a>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-8">
                <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                        <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId"
                                   placeholder="e.g., AB123456" />
                        <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                        <small class="form-text text-muted">Format: 2 uppercase letters followed by 6 digits</small>
                    </div>

                    <div class="mb-3">
                        <label for="courseSelect" class="form-label">Course</label>
                        <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                            <option value="0">— Select a course —</option>
                            @foreach (var course in _courses)
                            {
                                <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-link">Cancel</a>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private EnrollmentRequest _model = new();
    private List<Course> _courses = [];
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetAllCourses();

        if (CourseId.HasValue)
        {
            _model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourseById(_model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";
        _submitted = true;
    }
}
